// Hand-written wrapper for the NSX Global Manager GlobalInfra client, following the
// same ClientContext pattern as the autogenerated wrappers in this package (see
// infra.go, org_root.go): it hides the SDK client behind an interface{} field so it
// can be swapped for a mock in unit tests, and hides the local-model<->GM-model
// conversion behind the same method signatures used by the rest of the provider.
package nsxt

import (
	"errors"

	vapiProtocolClient_ "github.com/vmware/vsphere-automation-sdk-go/runtime/protocol/client"
	global_policy "github.com/vmware/vsphere-automation-sdk-go/services/nsxt-gm"
	model1 "github.com/vmware/vsphere-automation-sdk-go/services/nsxt-gm/model"
	model0 "github.com/vmware/vsphere-automation-sdk-go/services/nsxt/model"

	utl "github.com/vmware/terraform-provider-nsxt/api/utl"
)

type GlobalInfraClientContext utl.ClientContext

func NewGlobalInfraClient(sessionContext utl.SessionContext, connector vapiProtocolClient_.Connector) *GlobalInfraClientContext {
	var client interface{}

	switch sessionContext.ClientType {

	case utl.Global:
		client = global_policy.NewGlobalInfraClient(connector)

	default:
		return nil
	}
	return &GlobalInfraClientContext{Client: client, ClientType: sessionContext.ClientType, ProjectID: sessionContext.ProjectID, VPCID: sessionContext.VPCID}
}

func (c GlobalInfraClientContext) Patch(infraParam model0.Infra, enforceRevisionCheckParam *bool) error {
	var err error

	switch c.ClientType {

	case utl.Global:
		client := c.Client.(global_policy.GlobalInfraClient)
		gmObj, err1 := utl.ConvertModelBindingType(infraParam, model0.InfraBindingType(), model1.InfraBindingType())
		if err1 != nil {
			return err1
		}
		err = client.Patch(gmObj.(model1.Infra), enforceRevisionCheckParam)

	default:
		err = errors.New("invalid infrastructure for model")
	}
	return err
}
